<template><div class="player-page"><header class="player-header"><router-link to="/learning" class="back"><ArrowLeft :size="17"/> 내 학습</router-link><div><strong>{{ courseTitle }}</strong><span>{{ currentLesson.index }} / {{ lessons.length }}차시</span></div><div class="header-progress"><div class="progress"><span :style="`width:${progressRate}%`"></span></div><b>{{ progressRate }}%</b></div><button class="icon-button" aria-label="학습 화면 닫기" @click="$router.push('/learning')"><X :size="19"/></button></header><main class="player-layout"><section class="video-area"><div class="video-frame"><div class="video-brand"><span>LINGUA<span>ROUTE</span></span><small>LESSON {{ currentLesson.index }}</small></div><div class="slide-content"><p>KEY EXPRESSION</p><h1>{{ currentLesson.title }}</h1><span>등록된 학습 콘텐츠를 재생하고 완료 상태를 서버에 저장합니다.</span></div><button class="play-button" aria-label="재생"><Play :size="28" fill="currentColor"/></button><div class="video-controls"><button><Play :size="14" fill="currentColor"/></button><span>00:00</span><div class="video-timeline"><i></i></div><span>{{ currentLesson.length }}</span><button><Volume2 :size="15"/></button><button><Maximize :size="15"/></button></div></div><div class="lesson-info"><div><span class="tag">{{ currentLesson.index }}차시</span><h2>{{ currentLesson.title }}</h2><p>이 차시를 시작하면 학습 시작 시각이, 완료하면 진도율과 완료 시각이 서버에 저장됩니다.</p></div><button class="button accent" :disabled="completed" @click="completeCurrentLesson"><CircleCheck :size="16"/> {{ completed?'완료 처리됨':'이 차시 완료하기' }}</button></div><div class="learning-tools"><button class="active"><NotebookPen :size="16"/> 학습 노트</button><button><MessageSquareText :size="16"/> 핵심 표현</button><button><FileText :size="16"/> 학습 자료</button></div><div class="note-area"><textarea placeholder="이 차시에서 기억하고 싶은 내용을 적어두세요."></textarea><button class="button small">노트 저장</button></div></section><aside class="lesson-sidebar"><div class="sidebar-head"><span><strong>커리큘럼</strong><small>등록된 {{ lessons.length }}차시</small></span><button><PanelRightClose :size="17"/></button></div><div class="course-progress"><div><span>전체 진도</span><b>{{ progressRate }}%</b></div><div class="progress"><span :style="`width:${progressRate}%`"></span></div></div><div class="lesson-group"><p>CURRICULUM</p><button v-for="lesson in lessons" :key="lesson.id" :class="{active:lesson.id===currentLesson.id,done:lesson.status==='완료'}"><span>{{ lesson.status==='완료'?'✓':lesson.index }}</span><span><strong>{{ lesson.title }}</strong><small>{{ lesson.length }}</small></span><PlayCircle :size="17"/></button></div><div class="next-action"><span>학습 상태</span><strong>{{ feedback || '현재 차시를 완료하면 다음 학습으로 이동할 수 있어요.' }}</strong><router-link to="/learning" class="button primary">내 학습으로 <ArrowRight :size="15"/></router-link></div></aside></main></div></template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowLeft,X,Play,Volume2,Maximize,CircleCheck,NotebookPen,MessageSquareText,FileText,PanelRightClose,PlayCircle,ArrowRight } from '@lucide/vue'
import { lessons as mockLessons } from '@/data/mockData.js'
import { courseApi } from '@/api/course.js'
import { enrollmentApi } from '@/api/enrollment.js'

const route = useRoute()
const useLiveApi = import.meta.env.VITE_USE_LIVE_API === 'true'
const lessons = ref(mockLessons)
const courseTitle = ref('해외 고객 미팅 영어')
const progressRate = ref(68)
const completed = ref(false)
const feedback = ref('')
const currentLesson = computed(() => lessons.value.find((lesson) => lesson.id === Number(route.params.lessonId)) || lessons.value[0])

onMounted(async () => {
  if (!useLiveApi) return
  try {
    const detail = (await enrollmentApi.getById(route.params.enrollmentId)).data.data
    const [courseResponse, lessonResponse] = await Promise.all([courseApi.getById(detail.courseId), courseApi.getLessons(detail.courseId)])
    courseTitle.value = courseResponse.data.data.title
    progressRate.value = Number(detail.progressRate)
    const statusByLesson = new Map(detail.lessons.map((lesson) => [lesson.lessonId, lesson.status]))
    lessons.value = lessonResponse.data.data.map((lesson) => ({
      id: lesson.lessonId, index: String(lesson.sequence).padStart(2, '0'), title: lesson.title,
      length: `${Math.ceil(lesson.durationSeconds / 60)}분`, status: statusByLesson.get(lesson.lessonId) === 'COMPLETED' ? '완료' : '대기'
    }))
    completed.value = statusByLesson.get(Number(route.params.lessonId)) === 'COMPLETED'
    if (!completed.value) await enrollmentApi.startLesson(route.params.enrollmentId, route.params.lessonId)
  } catch (error) {
    feedback.value = error.response?.data?.message || '학습 정보를 불러오지 못했습니다.'
  }
})

async function completeCurrentLesson() {
  if (!useLiveApi) { completed.value = true; progressRate.value = 100; return }
  try {
    const result = (await enrollmentApi.completeLesson(route.params.enrollmentId, route.params.lessonId)).data.data
    completed.value = true
    progressRate.value = Number(result.progressRate)
    lessons.value = lessons.value.map((lesson) => lesson.id === Number(route.params.lessonId) ? { ...lesson, status: '완료' } : lesson)
    feedback.value = result.enrollmentStatus === 'COMPLETED' ? '강의를 모두 완료했습니다.' : '차시를 완료했습니다.'
  } catch (error) {
    feedback.value = error.response?.data?.message || '차시 완료 처리에 실패했습니다.'
  }
}
</script>
