isplay);font-size:clamp(26px,4vw,48px);letter-spacing:-.045em}.slide-content span{color:#9cb4a5;font-size:12px}.play-button{position:absolute;z-index:3;bottom:60px;left:50%;width:58px;height:58px;display:none;place-items:center;color:var(--ink);background:var(--lime);border-radius:50%}.video-controls{position:absolute;right:0;bottom:0;left:0;z-index:4;height:46px;display:flex;align-items:center;gap:10px;padding:0 14px;background:linear-gradient(transparent,rgba(0,0,0,.7));font-size:9px}.video-controls button{display:grid;place-items:center;color:white;background:transparent}.video-timeline{height:3px;flex:1;background:rgba(255,255,255,.25);border-radius:4px}.video-timeline i{display:block;width:33%;height:100%;background:var(--lime)}.lesson-info{display:flex;align-items:flex-start;justify-content:space-between;gap:30px;padding:24px 0;color:white;border-bottom:1px solid rgba(255,255,255,.09)}.lesson-info h2{margin:11px 0 7px;font-size:18px}.lesson-info p{max-width:670px;color:#82988a;font-size:10px;line-height:1.7}.learning-tools{display:flex;gap:4px;margin-top:20px}.learning-tools button{display:flex;align-items:center;gap:7px;padding:9px 12px;color:#769080;background:transparent;border-bottom:2px solid transparent;font-size:10px;font-weight:700}.learning-tools button.active{color:var(--lime);border-color:var(--lime)}.note-area{display:flex;align-items:flex-end;gap:10px;margin-top:10px}.note-area textarea{min-height:90px;flex:1;padding:13px;color:#d8e6dd;background:#17251d;border:1px solid rgba(255,255,255,.1);border-radius:10px;resize:vertical}.lesson-sidebar{display:flex;flex-direction:column;color:white;background:#17251d;border-left:1px solid rgba(255,255,255,.08)}.sidebar-head{height:68px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid rgba(255,255,255,.08)}.sidebar-head strong,.sidebar-head small{display:block}.sidebar-head strong{font-size:12px}.sidebar-head small{margin-top:2px;color:#789080;font-size:9px}.sidebar-head button{color:#789080;background:transparent}.course-progress{padding:17px 20px;background:#1b2d23}.course-progress>div{display:flex;justify-content:space-between;margin-bottom:7px;color:#8ca294;font-size:9px}.course-progress b{color:var(--lime)}.course-progress .progress{background:rgba(255,255,255,.1)}.course-progress .progress span{background:var(--lime)}.lesson-group{padding:15px 10px}.lesson-group>p{margin:5px 9px 9px;color:#5f7869;font-size:8px;font-weight:800;letter-spacing:.08em}.lesson-group button{width:100%;display:grid;grid-template-columns:26px 1fr auto;align-items:center;gap:9px;padding:11px;color:#a8b9ae;background:transparent;border-radius:9px;text-align:left}.lesson-group button.active{color:white;background:rgba(200,243,107,.09)}.lesson-group button>span:first-child{width:25px;height:25px;display:grid;place-items:center;color:#6f8a79;background:rgba(255,255,255,.05);border-radius:50%;font-size:8px}.lesson-group button.done>span:first-child{color:var(--ink);background:var(--lime)}.lesson-group button strong,.lesson-group button small{display:block}.lesson-group button strong{font-size:9px}.lesson-group button small{margin-top:3px;color:#627b6c;font-size:8px}.next-action{display:grid;gap:8px;margin:auto 12px 12px;padding:15px;background:#203328;border-radius:12px}.next-action span{color:#65806f;font-size:8px}.next-action strong{font-size:10px}.next-action .button{margin-top:4px}@media(max-width:900px){.player-layout{grid-template-columns:1fr}.lesson-sidebar{display:none}.video-area{padding:16px}.header-progress{display:none!important}}@media(max-width:600px){.player-header>div:nth-child(2){display:none}.video-frame{aspect-ratio:4/3}.slide-content h1{font-size:25px}.lesson-info{flex-direction:column}.lesson-info .button{width:100%}.note-area{align-items:stretch;flex-direction:column}}</style>
